import { Controller, Get, Post, Patch, Delete, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const ROLE = '예산·회계 담당자';
// 가정: 계좌번호 암호화 키 출처가 스펙에 없어 상수로 둔다. 운영에서는 DB와 분리된 키로 교체해야 한다.
const ACCOUNT_KEY = 'partner-account-key';
const USE_STATUSES = ['사용', '미사용'];

function invalid(message: string): ApiError {
  return new ApiError(400, 'VALIDATION_FAILED', message);
}

function idOf(value: unknown, label: string): string {
  const text = typeof value === 'number' ? String(value) : value;
  if (typeof text !== 'string' || !/^\d+$/.test(text)) {
    throw invalid(label + ' 값이 올바르지 않습니다.');
  }
  return text;
}

function textOf(value: unknown, label: string, required: boolean, max: number): string | null {
  if (value === undefined || value === null || value === '') {
    if (required) {
      throw invalid(label + '을(를) 입력해 주세요.');
    }
    return null;
  }
  if (typeof value !== 'string' || value.trim() === '' || value.trim().length > max) {
    throw invalid(label + ' 값이 올바르지 않습니다.');
  }
  return value.trim();
}

function statusOf(value: unknown): string | null {
  if (value === undefined || value === null || value === '') {
    return null;
  }
  if (typeof value !== 'string' || !USE_STATUSES.includes(value)) {
    throw invalid('사용 여부는 사용 또는 미사용이어야 합니다.');
  }
  return value;
}

@Controller('api/v1')
export class FnSfr00205Controller {
  @Get('/partner-accounts')
  async listPartnerAccounts(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const query = checks.queryOf(req.query);
    const partnerId = idOf(query['partnerId'], '거래처');
    const page = Math.max(0, parseInt(String(query['page'] ?? '0'), 10) || 0);
    const size = Math.min(200, Math.max(1, parseInt(String(query['size'] ?? '20'), 10) || 20));
    return transaction(async (db) => {
      const items = await db.query(
        `SELECT partner_account_id AS "partnerAccountId",
                partner_id AS "partnerId",
                bank_name AS "bankName",
                account_holder AS "accountHolder",
                use_status AS "useStatus"
           FROM partner_account
          WHERE partner_id = CAST(:partnerId AS bigint)
          ORDER BY partner_account_id
          LIMIT CAST(:size AS int) OFFSET CAST(:offset AS int)`,
        { partnerId, size, offset: page * size },
      );
      const counts = await db.query(
        `SELECT COUNT(*) AS "total" FROM partner_account WHERE partner_id = CAST(:partnerId AS bigint)`,
        { partnerId },
      );
      return { items, page, size, total: Number(counts[0]['total']) };
    });
  }

  @Post('/partner-accounts')
  @HttpCode(200)
  async createPartnerAccount(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body);
    const partnerId = idOf(data['partnerId'], '거래처');
    const bankName = textOf(data['bankName'], '은행', true, 100) as string;
    const accountNumber = textOf(data['accountNumber'], '계좌번호', true, 50) as string;
    const accountHolder = textOf(data['accountHolder'], '예금주', true, 100) as string;
    const useStatus = statusOf(data['useStatus']) ?? '사용';
    return transaction(async (db) => {
      const partners = await db.query(
        'SELECT 1 AS "found" FROM partner WHERE partner_id = CAST(:partnerId AS bigint)',
        { partnerId },
      );
      if (partners.length === 0) {
        throw new ApiError(404, 'PARTNER_NOT_FOUND', '거래처를 찾을 수 없습니다.');
      }
      const duplicates = await db.query(
        `SELECT 1 AS "found" FROM partner_account
          WHERE partner_id = CAST(:partnerId AS bigint)
            AND bank_name = :bankName
            AND pgp_sym_decrypt(decode(account_number_enc, 'base64'), CAST(:key AS text)) = :accountNumber`,
        { partnerId, bankName, accountNumber, key: ACCOUNT_KEY },
      );
      if (duplicates.length > 0) {
        throw new ApiError(409, 'PARTNER_ACCOUNT_DUPLICATED', '같은 거래처에 동일한 계좌가 이미 등록되어 있습니다.');
      }
      const rows = await db.query(
        `INSERT INTO partner_account
           (partner_id, bank_name, account_number_enc, account_holder, use_status, created_at, updated_at)
         VALUES
           (CAST(:partnerId AS bigint), :bankName,
            encode(pgp_sym_encrypt(CAST(:accountNumber AS text), CAST(:key AS text)), 'base64'),
            :accountHolder, :useStatus, now(), now())
         RETURNING partner_account_id AS "partnerAccountId"`,
        { partnerId, bankName, accountNumber, accountHolder, useStatus, key: ACCOUNT_KEY },
      );
      return { partnerAccountId: Number(rows[0]['partnerAccountId']) };
    });
  }

  @Patch('/partner-accounts/:partnerAccountId')
  @HttpCode(200)
  async updatePartnerAccount(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const partnerAccountId = idOf(req.params['partnerAccountId'], '거래처 계좌 ID');
    const data = checks.inputOf(req.body);
    const bankName = textOf(data['bankName'], '은행', false, 100);
    const accountNumber = textOf(data['accountNumber'], '계좌번호', false, 50);
    const accountHolder = textOf(data['accountHolder'], '예금주', false, 100);
    const useStatus = statusOf(data['useStatus']);
    return transaction(async (db) => {
      const found = await db.query(
        `SELECT partner_id AS "partnerId",
                bank_name AS "bankName",
                account_holder AS "accountHolder",
                use_status AS "useStatus",
                pgp_sym_decrypt(decode(account_number_enc, 'base64'), CAST(:key AS text)) AS "accountNumber"
           FROM partner_account
          WHERE partner_account_id = CAST(:partnerAccountId AS bigint)
          FOR UPDATE`,
        { partnerAccountId, key: ACCOUNT_KEY },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'PARTNER_ACCOUNT_NOT_FOUND', '거래처 계좌를 찾을 수 없습니다.');
      }
      const current = found[0];
      const nextBank = bankName ?? String(current['bankName']);
      const nextNumber = accountNumber ?? String(current['accountNumber']);
      const nextHolder = accountHolder ?? String(current['accountHolder']);
      const nextStatus = useStatus ?? String(current['useStatus']);
      const duplicates = await db.query(
        `SELECT 1 AS "found" FROM partner_account
          WHERE partner_id = CAST(:partnerId AS bigint)
            AND partner_account_id <> CAST(:partnerAccountId AS bigint)
            AND bank_name = :bankName
            AND pgp_sym_decrypt(decode(account_number_enc, 'base64'), CAST(:key AS text)) = :accountNumber`,
        {
          partnerId: String(current['partnerId']),
          partnerAccountId,
          bankName: nextBank,
          accountNumber: nextNumber,
          key: ACCOUNT_KEY,
        },
      );
      if (duplicates.length > 0) {
        throw new ApiError(409, 'PARTNER_ACCOUNT_DUPLICATED', '같은 거래처에 동일한 계좌가 이미 등록되어 있습니다.');
      }
      await db.execute(
        `UPDATE partner_account
            SET bank_name = :bankName,
                account_number_enc = encode(pgp_sym_encrypt(CAST(:accountNumber AS text), CAST(:key AS text)), 'base64'),
                account_holder = :accountHolder,
                use_status = :useStatus,
                updated_at = now()
          WHERE partner_account_id = CAST(:partnerAccountId AS bigint)`,
        {
          bankName: nextBank,
          accountNumber: nextNumber,
          accountHolder: nextHolder,
          useStatus: nextStatus,
          partnerAccountId,
          key: ACCOUNT_KEY,
        },
      );
      return { partnerAccountId: Number(partnerAccountId) };
    });
  }

  @Delete('/partner-accounts/:partnerAccountId')
  @HttpCode(200)
  async deletePartnerAccount(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const partnerAccountId = idOf(req.params['partnerAccountId'], '거래처 계좌 ID');
    return transaction(async (db) => {
      const count = await db.execute(
        'DELETE FROM partner_account WHERE partner_account_id = CAST(:partnerAccountId AS bigint)',
        { partnerAccountId },
      );
      if (count === 0) {
        throw new ApiError(404, 'PARTNER_ACCOUNT_NOT_FOUND', '거래처 계좌를 찾을 수 없습니다.');
      }
      return {};
    });
  }
}

