import { useState } from 'react';
import {
  call,
  useData,
  Badge,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Form,
  Field,
  TextInput,
  Select,
  LookupSelect,
  RefName,
  ErrorText,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

const STATUS_OPTIONS: [string, string][] = [
  ['사용', '사용'],
  ['미사용', '미사용'],
];

type Mode = { kind: 'create' } | { kind: 'edit'; row: Row } | { kind: 'delete'; row: Row } | null;

export default function FnSfr00205Page({ role, notify }: PageProps) {
  const [partnerInput, setPartnerInput] = useState<number | string>('');
  const [partnerId, setPartnerId] = useState<number | string>('');
  const [page, setPage] = useState(0);
  const [mode, setMode] = useState<Mode>(null);
  const size = 20;

  const list = useData<Page>(async () => {
    if (partnerId === '') {
      return { items: [], page: 0, size, total: 0 };
    }
    return call<Page>('GET', '/partner-accounts', role, undefined, { partnerId, page, size });
  }, [partnerId, page, role]);

  const done = (text: string) => {
    setMode(null);
    notify(text);
    list.reload();
  };

  const search = () => {
    setPage(0);
    setPartnerId(partnerInput);
  };

  const reset = () => {
    setPartnerInput('');
    setPartnerId('');
    setPage(0);
  };

  const rows = list.data?.items ?? [];

  return (
    <div className="doc">
      <h1>거래처 계좌</h1>
      <Filters onSearch={search} onReset={reset}>
        <Field label="거래처" required>
          <LookupSelect table="partner" role={role} value={partnerInput} onChange={setPartnerInput} />
        </Field>
      </Filters>
      <Band total={list.data?.total}>
        <button
          type="button"
          disabled={partnerId === ''}
          onClick={() => setMode({ kind: 'create' })}
        >
          계좌 등록
        </button>
      </Band>
      {list.error ? <ErrorText text={list.error} /> : null}
      <DataTable
        rows={rows}
        empty={partnerId === '' ? '거래처를 선택하고 조회해 주세요.' : '아직 등록한 계좌가 없습니다. 계좌 등록 버튼으로 첫 계좌를 등록해 주세요.'}
        columns={[
          { key: 'partnerId', label: '거래처', render: (r) => <RefName table="partner" role={role} value={r['partnerId']} /> },
          { key: 'bankName', label: '은행' },
          { key: 'accountHolder', label: '예금주' },
          { key: 'useStatus', label: '사용 여부', render: (r) => <Badge value={r['useStatus']} /> },
          {
            key: 'partnerAccountId',
            label: '처리',
            render: (r) => (
              <span>
                <button type="button" className="ghost" onClick={() => setMode({ kind: 'edit', row: r })}>
                  수정
                </button>
                <button type="button" className="ghost" onClick={() => setMode({ kind: 'delete', row: r })}>
                  삭제
                </button>
              </span>
            ),
          },
        ]}
      />
      <Pager page={page} size={size} total={list.data?.total ?? 0} onPage={setPage} />
      {mode?.kind === 'create' ? (
        <Drawer title="거래처 계좌 등록" onClose={() => setMode(null)}>
          <CreateForm role={role} partnerId={partnerId} onDone={done} />
        </Drawer>
      ) : null}
      {mode?.kind === 'edit' ? (
        <Drawer title="거래처 계좌 수정" onClose={() => setMode(null)}>
          <EditForm role={role} row={mode.row} onDone={done} />
        </Drawer>
      ) : null}
      {mode?.kind === 'delete' ? (
        <Drawer title="거래처 계좌 삭제" onClose={() => setMode(null)}>
          <DeleteForm role={role} row={mode.row} onDone={done} />
        </Drawer>
      ) : null}
    </div>
  );
}

function CreateForm({ role, partnerId, onDone }: { role: string; partnerId: number | string; onDone: (text: string) => void }) {
  const [bankName, setBankName] = useState('');
  const [accountNumber, setAccountNumber] = useState('');
  const [accountHolder, setAccountHolder] = useState('');
  const [useStatus, setUseStatus] = useState('사용');

  const submit = async () => {
    if (bankName.trim() === '' || accountNumber.trim() === '' || accountHolder.trim() === '') {
      throw new Error('은행, 계좌번호, 예금주를 모두 입력해 주세요.');
    }
    await call('POST', '/partner-accounts', role, { partnerId, bankName, accountNumber, accountHolder, useStatus });
    onDone('거래처 계좌를 등록했습니다.');
  };

  return (
    <Form onSubmit={submit} submit="등록">
      <Field label="거래처" required>
        <LookupSelect table="partner" role={role} value={partnerId} onChange={() => undefined} />
      </Field>
      <Field label="은행" required>
        <TextInput value={bankName} onChange={setBankName} />
      </Field>
      <Field label="계좌번호" required hint="암호화하여 저장합니다.">
        <TextInput value={accountNumber} onChange={setAccountNumber} />
      </Field>
      <Field label="예금주" required>
        <TextInput value={accountHolder} onChange={setAccountHolder} />
      </Field>
      <Field label="사용 여부">
        <Select value={useStatus} onChange={setUseStatus} options={STATUS_OPTIONS} />
      </Field>
    </Form>
  );
}

function EditForm({ role, row, onDone }: { role: string; row: Row; onDone: (text: string) => void }) {
  const [bankName, setBankName] = useState(String(row['bankName'] ?? ''));
  const [accountNumber, setAccountNumber] = useState('');
  const [accountHolder, setAccountHolder] = useState(String(row['accountHolder'] ?? ''));
  const [useStatus, setUseStatus] = useState(String(row['useStatus'] ?? '사용'));

  const submit = async () => {
    if (bankName.trim() === '' || accountHolder.trim() === '') {
      throw new Error('은행과 예금주를 입력해 주세요.');
    }
    const body: Row = { bankName, accountHolder, useStatus };
    if (accountNumber.trim() !== '') {
      body['accountNumber'] = accountNumber;
    }
    await call('PATCH', '/partner-accounts/' + String(row['partnerAccountId']), role, body);
    onDone('거래처 계좌를 수정했습니다.');
  };

  return (
    <Form onSubmit={submit} submit="저장">
      <Field label="은행" required>
        <TextInput value={bankName} onChange={setBankName} />
      </Field>
      <Field label="계좌번호" hint="바꿀 때만 입력합니다. 비우면 기존 계좌번호를 유지합니다.">
        <TextInput value={accountNumber} onChange={setAccountNumber} />
      </Field>
      <Field label="예금주" required>
        <TextInput value={accountHolder} onChange={setAccountHolder} />
      </Field>
      <Field label="사용 여부">
        <Select value={useStatus} onChange={setUseStatus} options={STATUS_OPTIONS} />
      </Field>
    </Form>
  );
}

function DeleteForm({ role, row, onDone }: { role: string; row: Row; onDone: (text: string) => void }) {
  const submit = async () => {
    await call('DELETE', '/partner-accounts/' + String(row['partnerAccountId']), role);
    onDone('거래처 계좌를 삭제했습니다.');
  };

  return (
    <Form
      onSubmit={submit}
      submit="삭제"
      danger
      note={<p>삭제한 계좌는 되돌릴 수 없습니다. 계속 쓰지 않으려면 삭제 대신 사용 여부를 미사용으로 바꿔 주세요.</p>}
    >
      <p>{String(row['bankName'] ?? '')} 계좌({String(row['accountHolder'] ?? '')})를 삭제합니다.</p>
    </Form>
  );
}
